"""Merge overlapping or touching integer intervals."""


def merge_intervals(intervals):
    """Merge integer [start, end] pairs that overlap or touch.

    Touching means end + 1 == next start, e.g. [1, 2] and [3, 4] -> [1, 4].
    Returns a new sorted list; the input is never mutated.
    Raises ValueError if any pair is reversed (start > end).
    """
    checked = []
    for item in intervals:
        pair = list(item)
        if len(pair) != 2:
            raise ValueError(f"interval must have exactly 2 values, got {pair!r}")
        start, end = pair
        if start > end:
            raise ValueError(f"reversed interval: start {start} > end {end}")
        checked.append((start, end))

    checked.sort()

    merged = []
    for start, end in checked:
        if merged and start <= merged[-1][1] + 1:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])

    return merged

