"""Tests for solution.merge_intervals. Run: python3 test_solution.py -v (or pytest)."""

import unittest

from solution import merge_intervals


class MergeIntervalsTest(unittest.TestCase):
    def test_overlap(self):
        self.assertEqual(merge_intervals([[1, 3], [2, 6], [8, 10]]), [[1, 6], [8, 10]])

    def test_touching_endpoints(self):
        self.assertEqual(merge_intervals([[1, 2], [3, 4]]), [[1, 4]])

    def test_one_apart_not_merged(self):
        self.assertEqual(merge_intervals([[1, 2], [4, 5]]), [[1, 2], [4, 5]])

    def test_unsorted_input(self):
        self.assertEqual(merge_intervals([[8, 10], [1, 3], [2, 6]]), [[1, 6], [8, 10]])

    def test_nested(self):
        self.assertEqual(merge_intervals([[1, 10], [2, 3], [4, 5]]), [[1, 10]])

    def test_duplicates(self):
        self.assertEqual(merge_intervals([[1, 5], [1, 5]]), [[1, 5]])

    def test_single_point(self):
        self.assertEqual(merge_intervals([[5, 5]]), [[5, 5]])

    def test_chain_of_touching(self):
        self.assertEqual(merge_intervals([[1, 1], [2, 2], [3, 3]]), [[1, 3]])

    def test_negative_and_zero(self):
        self.assertEqual(merge_intervals([[-5, -3], [-2, 0], [1, 1]]), [[-5, 1]])

    def test_empty(self):
        self.assertEqual(merge_intervals([]), [])

    def test_single_interval(self):
        self.assertEqual(merge_intervals([[-3, 7]]), [[-3, 7]])

    def test_tuple_input(self):
        self.assertEqual(merge_intervals([(1, 3), (3, 4)]), [[1, 4]])

    def test_does_not_mutate_input(self):
        original = [[8, 10], [1, 3], [2, 6]]
        snapshot = [list(p) for p in original]
        merge_intervals(original)
        self.assertEqual(original, snapshot)

        nested = [[1, 10], [2, 3]]
        nest_snapshot = [list(p) for p in nested]
        merge_intervals(nested)
        self.assertEqual(nested, nest_snapshot)

    def test_result_is_independent_copy(self):
        src = [[1, 3]]
        out = merge_intervals(src)
        out[0][0] = 99
        self.assertEqual(src, [[1, 3]])

    def test_reversed_raises(self):
        with self.assertRaises(ValueError):
            merge_intervals([[5, 2]])

    def test_reversed_raises_among_valid(self):
        with self.assertRaises(ValueError):
            merge_intervals([[1, 2], [9, 4]])

    def test_reversed_not_partially_reordered_on_error(self):
        data = [[5, 2], [1, 1]]
        snapshot = [list(p) for p in data]
        with self.assertRaises(ValueError):
            merge_intervals(data)
        self.assertEqual(data, snapshot)

    def test_bad_length_raises(self):
        with self.assertRaises(ValueError):
            merge_intervals([[1, 2, 3]])

    def test_generator_input(self):
        self.assertEqual(merge_intervals(iter([[1, 2], [3, 4]])), [[1, 4]])


if __name__ == "__main__":
    unittest.main(verbosity=2)

