"""Exact decimal ledger totals."""

from decimal import Decimal, InvalidOperation

__all__ = ["total"]


def _to_decimal(value, index):
    """Convert one row value to a finite Decimal, or raise ValueError."""
    if isinstance(value, Decimal):
        amount = value
    elif isinstance(value, bool):
        raise ValueError(f"malformed numeric value at row {index}: {value!r}")
    elif isinstance(value, int):
        amount = Decimal(value)
    elif isinstance(value, float):
        amount = Decimal(repr(value))
    else:
        text = str(value).strip()
        if not text:
            return None  # blank line: ignore
        try:
            amount = Decimal(text)
        except (InvalidOperation, ValueError, ArithmeticError):
            raise ValueError(
                f"malformed numeric value at row {index}: {value!r}"
            ) from None
    if not amount.is_finite():
        raise ValueError(f"malformed numeric value at row {index}: {value!r}")
    return amount


def total(rows):
    """Exact decimal total of a ledger.

    Blank lines (empty or whitespace-only) are ignored. Signed amounts
    ("-12.50", "+3") are accepted. Anything that is not a finite decimal
    number raises ValueError.
    """
    result = Decimal("0")
    for index, row in enumerate(rows):
        if row is None:
            continue
        amount = _to_decimal(row, index)
        if amount is None:
            continue
        result += amount
    return result
